//! Pure-Rust re-implementation of the `indicators` C++ helper library.
//!
//! All formatting reproduces the C++ behaviour byte-for-byte: percentages are
//! computed with `f32` arithmetic and rendered with fixed precision, bars use
//! `=` fill, a `>` head and space padding inside `[` `]`.

pub mod bar;
pub mod builder;
pub mod counter;
pub mod cyclic;
pub mod display;
pub mod format;
pub mod multi;
pub mod percentage;
pub mod task;
pub mod tracker;

pub use bar::ProgressBar;
pub use builder::ProgressBuilder;
pub use counter::Counter;
pub use cyclic::CyclicProgress;
pub use display::ProgressDisplay;
pub use format::Format;
pub use multi::MultiProgress;
pub use percentage::Percentage;
pub use task::TaskProgress;
pub use tracker::ProgressTracker;

/// Shared helper: percentage value (0..=100) from a fraction stored as `f32`.
pub(crate) fn percent_value(fraction: f32) -> f32 {
    fraction * 100.0
}

/// Format a fraction as a percentage string with the given precision, e.g.
/// `format_percent(0.45, 1)` -> `"45.0%"`.
pub(crate) fn format_percent(fraction: f32, precision: usize) -> String {
    format!("{:.prec$}%", percent_value(fraction), prec = precision)
}

use std::fmt;

use crate::format::Format;

/// A single progress bar with `[====>   ] 50.0%` rendering.
pub struct ProgressBar {
    progress: i64,
    total: i64,
    width: usize,
}

impl Default for ProgressBar {
    fn default() -> Self {
        ProgressBar {
            progress: 0,
            total: 100,
            width: 50,
        }
    }
}

impl ProgressBar {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn set_progress(&mut self, progress: i64) {
        self.progress = progress;
    }

    pub fn set_total(&mut self, total: i64) {
        self.total = total;
    }

    pub fn set_width(&mut self, width: usize) {
        self.width = width;
    }

    pub fn str(&self) -> String {
        Format::bar(self.progress, self.total, self.width)
    }
}

impl fmt::Display for ProgressBar {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.str())
    }
}

use std::fmt;

use crate::format_percent;

/// A percentage value with a fixed display precision, e.g. `"45.0%"`.
#[derive(Clone, Copy)]
pub struct Percentage {
    value: f32,
    precision: usize,
}

impl Percentage {
    pub fn new(value: f32, precision: usize) -> Self {
        Percentage { value, precision }
    }

    pub fn str(&self) -> String {
        format_percent(self.value, self.precision)
    }
}

impl fmt::Display for Percentage {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.str())
    }
}

impl From<Percentage> for String {
    fn from(p: Percentage) -> String {
        p.str()
    }
}

use std::fmt;

/// A simple `current/total` counter, e.g. `"45/90"`.
#[derive(Clone, Copy, Default)]
pub struct Counter {
    current: i64,
    total: i64,
}

impl Counter {
    pub fn new(current: i64, total: i64) -> Self {
        Counter { current, total }
    }

    pub fn set_current(&mut self, current: i64) {
        self.current = current;
    }

    pub fn set_total(&mut self, total: i64) {
        self.total = total;
    }

    pub fn str(&self) -> String {
        format!("{}/{}", self.current, self.total)
    }
}

impl fmt::Display for Counter {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.str())
    }
}

impl From<Counter> for String {
    fn from(c: Counter) -> String {
        c.str()
    }
}

use crate::format_percent;

/// Fluent builder that renders a one-decimal percentage, e.g. `"50.0%"`.
#[derive(Default)]
pub struct ProgressBuilder {
    progress: i64,
    total: i64,
}

impl ProgressBuilder {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn set_progress(&mut self, progress: i64) -> &mut Self {
        self.progress = progress;
        self
    }

    pub fn set_total(&mut self, total: i64) -> &mut Self {
        self.total = total;
        self
    }

    pub fn build(&self) -> String {
        let fraction = if self.total != 0 {
            self.progress as f32 / self.total as f32
        } else {
            0.0
        };
        format_percent(fraction, 1)
    }
}

use crate::format_percent;

/// Tracks progress across named stages.
#[derive(Default)]
pub struct ProgressTracker {
    stages: Vec<String>,
    progress: i64,
    total: i64,
}

impl ProgressTracker {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add_stage(&mut self, name: &str) -> &mut Self {
        self.stages.push(name.to_string());
        self
    }

    pub fn set_progress(&mut self, progress: i64) {
        self.progress = progress;
    }

    pub fn set_total(&mut self, total: i64) {
        self.total = total;
    }

    /// Renders `"current/total"`, e.g. `"1/3"`.
    pub fn get_progress(&self) -> String {
        format!("{}/{}", self.progress, self.total)
    }

    /// Renders the one-decimal percentage, e.g. `"33.3%"`.
    pub fn get_percentage(&self) -> String {
        let fraction = if self.total != 0 {
            self.progress as f32 / self.total as f32
        } else {
            0.0
        };
        format_percent(fraction, 1)
    }
}

use crate::format_percent;

/// Stateless formatting helpers mirroring `indicators::Format`.
pub struct Format;

impl Format {
    /// One-decimal percentage, e.g. `Format::percentage(0.33)` -> `"33.0%"`.
    pub fn percentage(value: f32) -> String {
        Self::percentage_p(value, 1)
    }

    /// Percentage with explicit precision.
    pub fn percentage_p(value: f32, precision: usize) -> String {
        format_percent(value, precision)
    }

    /// `"current/total"` counter string, e.g. `"33/100"`.
    pub fn progress(current: i64, total: i64) -> String {
        format!("{}/{}", current, total)
    }

    /// Full bar string: `[` + `=` * filled + `>` + spaces + `]` + ` 50.0%`.
    pub fn bar(progress: i64, total: i64, width: usize) -> String {
        let ratio = if total != 0 {
            progress as f64 / total as f64
        } else {
            0.0
        };
        let filled = (ratio * width as f64) as usize;
        let mut s = String::with_capacity(width + 16);
        s.push('[');
        for _ in 0..filled {
            s.push('=');
        }
        s.push('>');
        for _ in (filled + 1)..width {
            s.push(' ');
        }
        s.push(']');
        s.push(' ');
        let fraction = if total != 0 {
            progress as f32 / total as f32
        } else {
            0.0
        };
        s.push_str(&format_percent(fraction, 1));
        s
    }
}

use crate::bar::ProgressBar;

/// A collection of progress bars rendered as `"Bar N: ..."` lines.
#[derive(Default)]
pub struct MultiProgress {
    bars: Vec<ProgressBar>,
}

impl MultiProgress {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add_bar(&mut self, bar: ProgressBar) {
        self.bars.push(bar);
    }

    pub fn str(&self) -> String {
        let mut out = String::new();
        for (i, bar) in self.bars.iter().enumerate() {
            if i > 0 {
                out.push('\n');
            }
            out.push_str(&format!("Bar {}: {}", i + 1, bar.str()));
        }
        out
    }
}

use crate::format_percent;

/// Textual progress display: `"Progress: 50.0% (50/100)"`.
pub struct ProgressDisplay {
    current: i64,
    total: i64,
}

impl ProgressDisplay {
    pub fn new(total: i64) -> Self {
        ProgressDisplay { current: 0, total }
    }

    pub fn update(&mut self, current: i64) {
        self.current = current;
    }

    pub fn increment(&mut self, delta: i64) {
        self.current += delta;
    }

    pub fn display(&self) -> String {
        let fraction = if self.total != 0 {
            self.current as f32 / self.total as f32
        } else {
            0.0
        };
        format!(
            "Progress: {} ({}/{})",
            format_percent(fraction, 1),
            self.current,
            self.total
        )
    }
}

use crate::format_percent;

/// Braille spinner frames, matching the C++ cyclic indicator.
const FRAMES: [char; 8] = ['⣾', '⣽', '⣻', '⢿', '⡿', '⣟', '⣯', '⣷'];

/// Cyclic (spinner) progress: `"⣻ 20.0%"`.
pub struct CyclicProgress {
    current: i64,
    total: i64,
    frame: usize,
}

impl CyclicProgress {
    pub fn new(total: i64) -> Self {
        CyclicProgress {
            current: 0,
            total,
            frame: 0,
        }
    }

    pub fn next(&mut self) {
        self.current += 1;
        self.frame = (self.frame + 1) % FRAMES.len();
    }

    pub fn str(&self) -> String {
        let fraction = if self.total != 0 {
            self.current as f32 / self.total as f32
        } else {
            0.0
        };
        format!("{} {}", FRAMES[self.frame], format_percent(fraction, 1))
    }
}

use crate::format_percent;

/// Named task progress: `"Test: 3/10 - 30.0%"`.
pub struct TaskProgress {
    name: String,
    completed: i64,
    total: i64,
}

impl TaskProgress {
    pub fn new(name: &str, total: i64) -> Self {
        TaskProgress {
            name: name.to_string(),
            completed: 0,
            total,
        }
    }

    pub fn complete(&mut self, n: i64) {
        self.completed = n;
    }

    pub fn status(&self) -> String {
        let fraction = if self.total != 0 {
            self.completed as f32 / self.total as f32
        } else {
            0.0
        };
        format!(
            "{}: {}/{} - {}",
            self.name,
            self.completed,
            self.total,
            format_percent(fraction, 1)
        )
    }
}

//! Rust port of `tests/test20.cpp` — exercises the whole `indicators` API.

mod indicators;

use indicators::{
    Counter, CyclicProgress, Format, MultiProgress, Percentage, ProgressBar, ProgressBuilder,
    ProgressDisplay, ProgressTracker, TaskProgress,
};

fn main() {
    // 测试所有API的组合
    let mut bar = ProgressBar::new();
    bar.set_progress(45);
    bar.set_total(90);
    bar.set_width(40);
    println!("{}", bar.str());
    println!("{}", bar); // C++ `bar()` call operator

    let pct1 = Percentage::new(0.45, 1);
    let pct2 = Percentage::new(0.67, 2);
    println!("{}", pct1.str());
    println!("{}", pct2.str());
    println!("{}", String::from(pct1));

    let cnt = Counter::new(45, 90);
    println!("{}", cnt.str());
    println!("{}", String::from(cnt));

    let mut builder = ProgressBuilder::new();
    println!("{}", builder.set_progress(45).set_total(90).build());

    let mut tracker = ProgressTracker::new();
    tracker.add_stage("A").add_stage("B").add_stage("C");
    tracker.set_progress(1);
    tracker.set_total(3);
    println!("{}", tracker.get_progress());
    println!("{}", tracker.get_percentage());

    println!("{}", Format::percentage(0.33));
    println!("{}", Format::progress(33, 100));
    println!("{}", Format::bar(33, 100, 25));

    let mut multi = MultiProgress::new();
    let mut b1 = ProgressBar::new();
    let mut b2 = ProgressBar::new();
    b1.set_progress(30);
    b1.set_total(100);
    b2.set_progress(60);
    b2.set_total(100);
    multi.add_bar(b1);
    multi.add_bar(b2);
    println!("{}", multi.str());

    let mut display = ProgressDisplay::new(100);
    display.update(50);
    println!("{}", display.display());
    display.increment(25);
    println!("{}", display.display());

    let mut cyclic = CyclicProgress::new(10);
    cyclic.next();
    cyclic.next();
    println!("{}", cyclic.str());

    let mut task = TaskProgress::new("Test", 10);
    task.complete(3);
    println!("{}", task.status());

    // 测试不同精度的百分比
    for i in 1..=5 {
        println!("{}", Format::percentage_p(0.12345, i));
    }

    // 测试不同宽度的进度条
    let mut i = 10;
    while i <= 50 {
        println!("{}", Format::bar(50, 100, i));
        i += 10;
    }

    // 测试计数器数组
    let mut counters = [Counter::default(); 3];
    for (i, c) in counters.iter_mut().enumerate() {
        let i = i as i64;
        c.set_current((i + 1) * 25);
        c.set_total(100);
        println!("{}", c.str());
    }

    // 测试百分比数组
    let percentages = [
        Percentage::new(0.25, 1),
        Percentage::new(0.5, 2),
        Percentage::new(0.75, 3),
    ];
    for p in &percentages {
        println!("{}", p.str());
    }
}
